CREATE COLUMN TABLE "TEST_AP"."ARSC2" ("ResCode" NVARCHAR(50) NOT NULL , "PriceList" INTEGER CS_INT NOT NULL , "Price" DECIMAL(21,6) CS_FIXED, "Currency" NVARCHAR(3), "Ovrwritten" NVARCHAR(1) DEFAULT 'N', "Factor" DECIMAL(21,6) CS_FIXED, "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "ObjType" NVARCHAR(20) DEFAULT '290', "AddPrice1" DECIMAL(21,6) CS_FIXED, "Currency1" NVARCHAR(3), "AddPrice2" DECIMAL(21,6) CS_FIXED, "Currency2" NVARCHAR(3), "Ovrwrite1" NVARCHAR(1) DEFAULT 'N', "Ovrwrite2" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("ResCode", "PriceList", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "ARSC2_CURRENCY" ON "TEST_AP"."ARSC2" ( "Currency" ASC );
CREATE INDEX "ARSC2_PRICE_LIST" ON "TEST_AP"."ARSC2" ( "PriceList" ASC );
CREATE INDEX "ARSC2_MANUAL" ON "TEST_AP"."ARSC2" ( "Ovrwritten" ASC )